import logging

from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.interfaces.FDSW18A.autoconnection import AutoConfiguration18A
from taf.fdsw.rc.schemas.FDSW19.autoconnection import AutoConnection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoConfiguration19(AutoConfiguration18A):

    def get_autoconnection_parameters(self, timeout=10):
        autoconnection = self.autoconnection_parameters()
        get_autoconnection_parameters = AutoConnection.from_object_dict(data=autoconnection.data)
        return get_autoconnection_parameters.to_dict()

    def enable_autoconfiguration_service(self, timeout):
        resp = self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"configuration": {'mode': 'Automatic'}}}
        )
        if resp.status is False:
            raise OperationFailure(resp.error)

    def disable_autoconfiguration_service(self, timeout):
        resp = self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"configuration": {'mode': 'Manual'}}}
        )
        if resp.status is False:
            raise OperationFailure(resp.error)
